arguments.command:
cd /tmp/sv-9a9aa73dd6c047ab8a41af1e51132173/moderate-version-conflicts && cat baseline-packages.json | python3 -c "
import json, sys
data = json.load(sys.stdin)
for proj in data.get('projects', []):
    name = proj['path'].split('/')[-1]
    for fw in proj.get('frameworks', []):
        for pkg in fw.get('topLevelPackages', []):
            print(f'{name}: {pkg[\"id\"]} {pkg.get(\"resolvedVersion\", pkg.get(\"requestedVersion\",\"?\"))}')
" 2>/dev/null

